import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class TradeExecutionServiceTest {

    @Mock TradeRepository tradeRepo;
    @Mock PriceService priceService;
    @Mock PostTradeProcessor postProcessor;
    @InjectMocks TradeExecutionService tradeService;

    @Test
    void shouldExecuteTradeAndTriggerAsyncProcessing() {
        when(priceService.getLatestPrice("RELIANCE")).thenReturn(new BigDecimal("2450.50"));
        when(tradeRepo.save(any(Trade.class))).thenAnswer(i -> i.getArgument(0));

        TradeResponse response = tradeService.executeTrade(
            new TradeRequest("SAV2001", "RELIANCE", "BUY", 100, new BigDecimal("2450.50")));

        assertThat(response.status()).isEqualTo("EXECUTED");
        verify(tradeRepo).save(any(Trade.class));
        verify(postProcessor).processAfterTrade(anyString(), eq("SAV2001"));
    }
}
